const fs = require('fs');
const path = require('path');
const readline = require('readline');

async function searchAllLogs() {
  const brainDir = 'C:\\Users\\Hype\\.gemini\\antigravity-ide\\brain';
  const dirs = fs.readdirSync(brainDir);
  for (const d of dirs) {
    const fullLog = path.join(brainDir, d, '.system_generated', 'logs', 'transcript_full.jsonl');
    if (fs.existsSync(fullLog)) {
      console.log('Checking log:', fullLog);
      const fileStream = fs.createReadStream(fullLog);
      const rl = readline.createInterface({ input: fileStream, crlfDelay: Infinity });
      for await (const line of rl) {
        if (line.includes('write_to_file') && line.includes('marketplace-orders-page.tsx')) {
          console.log('Found write_to_file in conv:', d, 'lineLen:', line.length);
          fs.writeFileSync('scratch/found_write.json', line);
        }
      }
    }
  }
}
searchAllLogs();
